 8→function getparams(data) {
 9→  /**
10→   * The workhorse; converts an object to x-www-form-urlencoded serialization.
11→   * @param {Object} obj
12→   * @return {String}
13→   */
14→  var param = function(obj) {
15→    var query = '';
16→    var name, value, fullSubName, subName, subValue, innerObj, i;
17→
18→    for (name in obj) {
19→      value = obj[name];
20→
21→      if (value instanceof Array) {
22→        for (i = 0; i < value.length; ++i) {
23→          subValue = value[i];
24→          fullSubName = name + '[' + i + ']';
25→          innerObj = {};
26→          innerObj[fullSubName] = subValue;
27→          query += param(innerObj) + '&';
28→        }
29→      } else if (value instanceof Object) {
30→        for (subName in value) {
31→          subValue = value[subName];
32→          fullSubName = name + '[' + subName + ']';
33→          innerObj = {};
34→          innerObj[fullSubName] = subValue;
35→          query += param(innerObj) + '&';
36→        }
37→      } else if (value !== undefined && value !== null) {
38→        query += encodeURIComponent(name) + '='
39→          + encodeURIComponent(value) + '&';
40→      }
41→    }
42→
43→    return query.length ? query.substr(0, query.length - 1) : query;
44→  }
45→  function isObject(value){return value != null && typeof value === 'object';}
46→  return isObject(data) && String(data) !== '[object File]'
47→    ? param(data)
48→    : data;
49→}
