     1→export interface QueryCondition {
     2→  andCondition: { fieldName: string; condition: string; value: any }[];
     3→  orCondition: { fieldName: string; condition: string; value: any }[];
     4→  page?: number;
     5→  pageSize?: number;
     6→  orderField?: string;
     7→  order?: string;
     8→}
