    10→export interface QueryBuilder {
    11→  and(column: string, condition: string, value: any): QueryBuilder;
    12→  or(column: string, condition: string, value: any): QueryBuilder;
    13→  page(page: number, size: number): QueryBuilder;
    14→  order(field: string, orderType: string): QueryBuilder;
    15→  value(): QueryCondition;
    16→}
    17→
    18→export default {
    19→  /**
    20→   * 获取build的实例
    21→   */
    22→  instance(condition?: QueryCondition): QueryBuilder {
    23→    const queryCondition: QueryCondition = condition || { andCondition: [], orCondition: [] };
    24→
    25→    return {
    26→      and(column: string, condition: string, value: any): QueryBuilder {
    27→        if (value !== "" && value !== undefined) {
    28→          let processedValue = value;
    29→          // 对于LIKE查询，转义SQL通配符
    30→          if (condition === 'like' && typeof processedValue === 'string') {
    31→            processedValue = processedValue.replace(/([_%\\])/g, '\\$1');
    32→          }
    33→          queryCondition.andCondition.push({ fieldName: column, condition, value: processedValue });
    34→        }
    35→        return this;
    36→      },
    37→      or(column: string, condition: string, value: any): QueryBuilder {
    38→        if (value !== "" && value !== undefined) {
    39→          let processedValue = value;
    40→          // 对于LIKE查询，转义SQL通配符
    41→          if (condition === 'like' && typeof processedValue === 'string') {
    42→            processedValue = processedValue.replace(/([_%\\])/g, '\\$1');
    43→          }
    44→          queryCondition.orCondition.push({ fieldName: column, condition, value: processedValue });
    45→        }
    46→        return this;
    47→      },
    48→      page(page: number, size: number): QueryBuilder {
    49→        queryCondition.page = page;
    50→        queryCondition.pageSize = size;
    51→        return this;
    52→      },
    53→      order(field: string, orderType: string): QueryBuilder {
    54→        queryCondition.orderField = field;
    55→        queryCondition.order = orderType;
    56→        return this;
    57→      },
    58→      value(): QueryCondition {
    59→        return queryCondition;
    60→      },
    61→    };
    62→  },
    63→  
    64→  /**
    65→   * 兼容旧的方法名，指向instance方法
    66→   */
    67→  getBuilder(condition?: QueryCondition): QueryBuilder {
    68→    return this.instance(condition);
    69→  },
    70→};
