    13→	let arr = tableData.map(item => item[label] ? item[label] : item[prop])
    14→	arr.push(label ? label : prop)//拼接内容和表头数据
    15→	const contentWidths = arr.map(item => {
    16→		const value = item ? String(item) : ''
    17→		const textWidth = getTextWidth(value)
    18→		return textWidth + padding + 20
    19→	})
    20→	const maxWidth = Math.max(...contentWidths)
    21→	return Math.max(minWidth, maxWidth)
    22→}
    23→
    24→/**
    25→ * el-table扩展工具  -- 列宽度自适应 - 获取列宽内文本宽度
    26→ * @param {*} text 文本内容
    27→ * @returns 文本宽度(int)
    28→ */
    29→export function getTextWidth(text) {
    30→	const span = document.createElement('span')
    31→	span.style.visibility = 'hidden'
    32→	span.style.position = 'absolute'
    33→	span.style.top = '-9999px'
    34→	span.style.whiteSpace = 'nowrap'
    35→	span.innerText = text
    36→	document.body.appendChild(span)
    37→	const width = span.offsetWidth + 100
    38→	document.body.removeChild(span)
    39→	return width
    40→}
    41→
    42→export function calculateWidth(str) {
    43→	// 假设一个汉字占 20px，一个字母或数字占 10px
    44→	if (!str) {
    45→		return 50;
    46→	}
    47→	let width = 0;
    48→	for (let char of str) {
    49→		if (/[\u4e00-\u9fff]/.test(char)) {
    50→			width += 18;
    51→		} else {
    52→			width += 12;
    53→		}
    54→	}
    55→	return width;
    56→}
    57→
    58→
    59→/**
    60→ * 方法用于格式化大小
    61→ * 如果参数不是数字
    62→ * @param size
    63→ * @returns {string}
    64→ */
    65→export function formattedSize(size) {
    66→	// 检查 size 是否为数字
    67→	if (!size || typeof size !== 'number' || isNaN(size)) {
    68→		return '-';
    69→	}
    70→
    71→	const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
    72→	let index = 0;
    73→	let number = size;
    74→
    75→	while (number >= 1024 && index < units.length - 1) {
    76→		number /= 1024;
    77→		index++;
    78→	}
    79→
    80→	return number.toFixed(2) + ' ' + units[index];
    81→}

