     1→// templateProcessor.js
     2→
     3→// 正则匹配 {{变量名}}、{{变量名.子变量名}}、{{变量名[数组索引]}}
     4→const PLACEHOLDER_PATTERN = /\{\{([^}]+)\}\}/g;
     5→
     6→/**
     7→ * 处理模板字符串，替换占位符
     8→ * @param {string} template - 模板字符串
     9→ * @param {Object} params - 参数对象
    10→ * @returns {string} 处理后的字符串
    11→ */
    12→function processTemplate(template, params) {
    13→	return template.replace(PLACEHOLDER_PATTERN, (match, placeholder) => {
    14→		const value = resolveValue(placeholder, params);
    15→		return value === null ? match : (typeof value === 'string' ? value : JSON.stringify(value));
    16→	});
    17→}
    18→
    19→/**
    20→ * 根据占位符路径解析值
    21→ * @param {string} path - 占位符路径
    22→ * @param {Object} params - 参数对象
    23→ * @returns {*} 解析后的值
    24→ */
    25→function resolveValue(path, params) {
    26→	const parts = path.split('.'); // 按点分割路径
    27→	let current = params;
    28→
    29→	for (const part of parts) {
    30→		if (current === null) {
    31→			return null; // 中间路径为空，直接返回 null
    32→		}
    33→		if (part.includes('[')) {
    34→			// 处理数组索引：变量名[索引]
    35→			const startIdx = part.indexOf('[');
    36→			const endIdx = part.indexOf(']');
    37→			const arrayKey = part.substring(0, startIdx);
    38→			const index = parseInt(part.substring(startIdx + 1, endIdx));
    39→
    40→			if (Array.isArray(current)) {
    41→				current = current[index];
    42→			} else if (current && typeof current === 'object') {
    43→				current = current[arrayKey];
    44→				if (Array.isArray(current)) {
    45→					current = current[index];
    46→				}
    47→			} else {
    48→				return null; // 非法路径
    49→			}
    50→		} else {
    51→			// 普通键值
    52→			if (current && typeof current === 'object') {
    53→				current = current[part];
    54→			} else {
    55→				return null; // 非法路径
    56→			}
    57→		}
    58→	}
    59→	return current;
    60→}
    61→
    62→export { processTemplate, resolveValue };
    63→

