 6→/**
 7→ * 为常见的滚动阻塞事件设置被动监听器的默认行为
 8→ * 这个方法应该在应用初始化时调用
 9→ */
10→export function setupPassiveListeners() {
11→  // 检查浏览器是否支持被动监听器
12→  let supportsPassive = false;
13→  try {
14→    const opts = Object.defineProperty({}, 'passive', {
15→      get() {
16→        supportsPassive = true;
17→        return false;
18→      }
19→    });
20→    window.addEventListener("testPassive", null, opts);
21→    window.removeEventListener("testPassive", null, opts);
22→  } catch (e) {
23→    console.warn('浏览器不支持被动事件监听器');
24→  }
25→
26→  if (!supportsPassive) {
27→    return;
28→  }
29→
30→  // 重写 addEventListener 来为滚动相关事件设置默认的被动行为
31→  const originalAddEventListener = EventTarget.prototype.addEventListener;
32→  
33→  EventTarget.prototype.addEventListener = function(type, listener, options) {
34→    // 需要设置为被动的事件类型
35→    const passiveEvents = [
36→      'touchstart',
37→      'touchmove', 
38→      'touchend',
39→      'touchcancel',
40→      'wheel',
41→      'mousewheel',
42→      'scroll'
43→    ];
44→
45→    // 如果是滚动相关事件且没有明确设置 passive 选项
46→    if (passiveEvents.includes(type)) {
47→      if (typeof options === 'boolean') {
48→        // 如果 options 是布尔值，转换为对象格式
49→        options = {
50→          capture: options,
51→          passive: true
52→        };
53→      } else if (typeof options === 'object' && options !== null) {
54→        // 如果 options 是对象且没有设置 passive，默认设置为 true
55→        if (!('passive' in options)) {
56→          options = { ...options, passive: true };
57→        }
58→      } else {
59→        // 如果没有 options 或为 null/undefined，设置默认的被动选项
60→        options = { passive: true };
61→      }
62→    }
63→
64→    return originalAddEventListener.call(this, type, listener, options);
65→  };
66→
67→}
