     8→ * - 带 RELOAD 前缀的 JSON 数组（切换会话重新加载时）
     9→ *
    10→ * @param {string} content - 原始内容
    11→ * @returns {Object} 解析结果：{ type: 'chain', chain: [...] } 或 { type: 'text', content: '...' }
    12→ */
    13→export function parseReasoningContent(content) {
    14→  if (!content || typeof content !== 'string') {
    15→    return { type: 'text', content: content || '' }
    16→  }
    17→
    18→  // RELOAD 前缀 = 完整历史数据，去掉前缀
    19→  let raw = content
    20→  if (raw.startsWith('RELOAD')) {
    21→    raw = raw.substring(6)
    22→  }
    23→
    24→  // JSON 数组格式 → 解析为结构化数据
    25→  if (raw.startsWith('[{') && raw.endsWith('}]')) {
    26→    try {
    27→      const parsed = JSON.parse(raw)
    28→      if (Array.isArray(parsed) && parsed.some(item => item.type === 'TOOL_CALL' || item.type === 'THINKING')) {
    29→        return { type: 'chain', chain: parsed }
    30→      }
    31→    } catch {
    32→      // 解析失败，作为纯文本处理
    33→    }
    34→  }
    35→
    36→  return { type: 'text', content }
    37→}
    38→

