     4→/**
     5→ * 解析消息配置为节点树
     6→ * @param {Object} config - 消息配置对象，支持两种格式：
     7→ *   1. 标准格式：{ version, meta, nodes: [...] }
     8→ *   2. 简化格式：直接是 nodes 数组或单个 node 对象
     9→ * @returns {Array} 节点数组
    10→ */
    11→export const parseMessageConfig = (config) => {
    12→  if (!config) return []
    13→  
    14→  // 如果 config 本身就是数组，直接返回
    15→  if (Array.isArray(config)) {
    16→    return config
    17→  }
    18→  
    19→  // 如果是标准格式（包含 nodes 字段）
    20→  if (config.nodes && Array.isArray(config.nodes)) {
    21→    return config.nodes
    22→  }
    23→  
    24→  // 如果是单个节点对象，包装成数组
    25→  if (config.type && typeof config === 'object') {
    26→    return [config]
    27→  }
    28→  
    29→  // 其他情况返回空数组
    30→  return []
    31→}
    32→
    33→/**
    34→ * 从消息内容中提取 JSON 配置
    35→ * @param {string} content - 消息内容字符串
    36→ * @returns {Object|null} 提取的 JSON 配置对象
    37→ */
    38→export const extractConfigFromContent = (content) => {
    39→  if (!content || typeof content !== 'string') return null
    40→  
    41→  try {
    42→    // 尝试提取 ```json ... ``` 代码块
    43→    const jsonPattern = /```json\s*([\s\S]*?)\s*```/gi
    44→    const match = jsonPattern.exec(content)
    45→    
    46→    if (match) {
    47→      try {
    48→        const cleanJson = match[1].trim()
    49→        const parsed = JSON.parse(cleanJson)
    50→        if (typeof parsed === 'object' && parsed !== null) {
    51→          return parsed
    52→        }
    53→      } catch (e) {
    54→        console.error('JSON解析失败:', e)
    55→        return null
    56→      }
    57→    }
    58→    
    59→    // 尝试直接解析整个内容为 JSON（如果内容本身就是 JSON）
    60→    try {
    61→      const parsed = JSON.parse(content.trim())
    62→      if (typeof parsed === 'object' && parsed !== null) {
    63→        return parsed
    64→      }
    65→    } catch (e) {
    66→      // 不是 JSON，忽略
    67→    }
    68→    
    69→    return null
    70→  } catch (error) {
    71→    console.error('提取配置失败:', error)
    72→    return null
    73→  }
    74→}
    75→
    76→export default {
    77→  parseMessageConfig,
    78→  extractConfigFromContent
    79→}
