     1→// ConfigValidator
     2→// 用于校验 AI 返回的页面/消息配置是否符合预期 schema
     3→
     4→/**
     5→ * 验证消息配置
     6→ * @param {Object} config - 消息配置对象
     7→ * @param {Object} schema - Schema 定义（可选）
     8→ * @returns {Object} { valid: boolean, errors: string[] }
     9→ */
    10→export const validateMessageConfig = (config, schema) => {
    11→  const errors = []
    12→  
    13→  if (!config) {
    14→    return { valid: false, errors: ['配置为空'] }
    15→  }
    16→  
    17→  // 如果是标准格式，检查 nodes 字段
    18→  if (config.nodes !== undefined) {
    19→    if (!Array.isArray(config.nodes)) {
    20→      errors.push('nodes 必须是数组')
    21→    } else if (config.nodes.length === 0) {
    22→      // 允许空数组，但给出警告
    23→      console.warn('配置中的 nodes 数组为空')
    24→    }
    25→  }
    26→  
    27→  // 如果 config 本身就是数组，验证数组中的节点
    28→  if (Array.isArray(config)) {
    29→    config.forEach((node, index) => {
    30→      if (!node || typeof node !== 'object') {
    31→        errors.push(`节点 ${index} 必须是对象`)
    32→      } else if (!node.type) {
    33→        errors.push(`节点 ${index} 缺少 type 字段`)
    34→      }
    35→    })
    36→  }
    37→  
    38→  // 如果是单个节点对象，验证基本字段
    39→  if (!Array.isArray(config) && config.nodes === undefined) {
    40→    if (!config.type) {
    41→      errors.push('节点缺少 type 字段')
    42→    }
    43→  }
    44→  
    45→  return {
    46→    valid: errors.length === 0,
    47→    errors
    48→  }
    49→}
    50→
    51→/**
    52→ * 验证单个节点
    53→ * @param {Object} node - 节点对象
    54→ * @returns {Object} { valid: boolean, errors: string[] }
    55→ */
    56→export const validateNode = (node) => {
    57→  const errors = []
    58→  
    59→  if (!node || typeof node !== 'object') {
    60→    return { valid: false, errors: ['节点必须是对象'] }
    61→  }
    62→  
    63→  if (!node.type) {
    64→    errors.push('节点缺少 type 字段')
    65→  }
    66→  
    67→  if (!node.id) {
    68→    // id 不是必须的，但建议有，这里只警告
    69→    console.warn('节点缺少 id 字段，建议添加以便调试')
    70→  }
    71→  
    72→  // 如果有 children，递归验证
    73→  if (node.children && Array.isArray(node.children)) {
    74→    node.children.forEach((child, index) => {
    75→      const childValidation = validateNode(child)
    76→      if (!childValidation.valid) {
    77→        errors.push(`子节点 ${index}: ${childValidation.errors.join(', ')}`)
    78→      }
    79→    })
    80→  }
    81→  
    82→  return {
    83→    valid: errors.length === 0,
    84→    errors
    85→  }
    86→}
    87→
    88→export default {
    89→  validateMessageConfig,
    90→  validateNode
    91→}
