     4→import { reactive, inject, provide } from 'vue'
     5→
     6→const REGISTRY_SYMBOL = Symbol('MessageComponentRegistry')
     7→
     8→export const createMessageComponentRegistry = () => {
     9→  const state = reactive({
    10→    components: new Map()
    11→  })
    12→
    13→  const register = (type, component) => {
    14→    if (!type || !component) return
    15→    state.components.set(type, component)
    16→  }
    17→
    18→  const unregister = (type) => {
    19→    state.components.delete(type)
    20→  }
    21→
    22→  const get = (type) => {
    23→    return state.components.get(type)
    24→  }
    25→
    26→  const list = () => {
    27→    return Array.from(state.components.keys())
    28→  }
    29→
    30→  const registry = {
    31→    register,
    32→    unregister,
    33→    get,
    34→    list
    35→  }
    36→
    37→  return registry
    38→}
    39→
    40→export const provideMessageComponentRegistry = (registry) => {
    41→  provide(REGISTRY_SYMBOL, registry)
    42→}
    43→
    44→export const useMessageComponentRegistry = () => {
    45→  return inject(REGISTRY_SYMBOL, createMessageComponentRegistry())
    46→}
    47→
    48→export default {
    49→  createMessageComponentRegistry,
    50→  provideMessageComponentRegistry,
    51→  useMessageComponentRegistry
    52→}
